/// Raven `GetFlagStr`.
///
/// Builds a human-readable waypoint-flag string into a `B_TempAlloc`'d
/// scratch buffer (128 bytes) — ports 1:1 as raw-pointer byte writes since
/// `B_TempAlloc`/`B_TempFree` are the (parked-elsewhere) allocator seam and
/// this function touches no file-scope globals itself.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:25-210`
pub fn GetFlagStr(
    ctx: GameContext<'_>,flags: c_int) -> *mut c_char {
    // Raven flag bit values (`ai_main.h:22-38`); not yet ported anywhere else
    // in the crate graph, so defined locally, verbatim.
    const WPFLAG_JUMP: c_int = 0x00000010;
    const WPFLAG_DUCK: c_int = 0x00000020;
    const WPFLAG_NOVIS: c_int = 0x00000400;
    const WPFLAG_SNIPEORCAMPSTAND: c_int = 0x00000800;
    const WPFLAG_WAITFORFUNC: c_int = 0x00001000;
    const WPFLAG_SNIPEORCAMP: c_int = 0x00002000;
    const WPFLAG_ONEWAY_FWD: c_int = 0x00004000;
    const WPFLAG_ONEWAY_BACK: c_int = 0x00008000;
    const WPFLAG_GOALPOINT: c_int = 0x00010000;
    const WPFLAG_RED_FLAG: c_int = 0x00020000;
    const WPFLAG_BLUE_FLAG: c_int = 0x00040000;
    const WPFLAG_SIEGE_REBELOBJ: c_int = 0x00080000;
    const WPFLAG_SIEGE_IMPERIALOBJ: c_int = 0x00100000;
    const WPFLAG_NOMOVEFUNC: c_int = 0x00200000;

    unsafe {
        let flagstr = B_TempAlloc(ctx, 128) as *mut c_char;
        let mut i: isize = 0;

        // Local helper mirroring the C `flagstr[i] = 'x'; i++;` idiom.
        macro_rules! put {
            ($c:expr) => {{
                *flagstr.offset(i) = $c as c_char;
                i += 1;
            }};
        }

        if flags == 0 {
            let s = b"none\0";
            for (n, b) in s.iter().enumerate() {
                *flagstr.offset(n as isize) = *b as c_char;
            }
            return flagstr;
        }

        if flags & WPFLAG_JUMP != 0 {
            put!(b'j');
        }
        if flags & WPFLAG_DUCK != 0 {
            put!(b'd');
        }
        if flags & WPFLAG_SNIPEORCAMPSTAND != 0 {
            put!(b'c');
        }
        if flags & WPFLAG_WAITFORFUNC != 0 {
            put!(b'f');
        }
        if flags & WPFLAG_SNIPEORCAMP != 0 {
            put!(b's');
        }
        if flags & WPFLAG_ONEWAY_FWD != 0 {
            put!(b'x');
        }
        if flags & WPFLAG_ONEWAY_BACK != 0 {
            put!(b'y');
        }
        if flags & WPFLAG_GOALPOINT != 0 {
            put!(b'g');
        }
        if flags & WPFLAG_NOVIS != 0 {
            put!(b'n');
        }
        if flags & WPFLAG_NOMOVEFUNC != 0 {
            put!(b'm');
        }

        if flags & WPFLAG_RED_FLAG != 0 {
            if i != 0 {
                put!(b' ');
            }
            for b in b"red flag" {
                put!(*b);
            }
        }

        if flags & WPFLAG_BLUE_FLAG != 0 {
            if i != 0 {
                put!(b' ');
            }
            for b in b"blue flag" {
                put!(*b);
            }
        }

        if flags & WPFLAG_SIEGE_IMPERIALOBJ != 0 {
            if i != 0 {
                put!(b' ');
            }
            for b in b"saga_imp" {
                put!(*b);
            }
        }

        if flags & WPFLAG_SIEGE_REBELOBJ != 0 {
            if i != 0 {
                put!(b' ');
            }
            for b in b"saga_reb" {
                put!(*b);
            }
        }

        *flagstr.offset(i) = 0;

        if i == 0 {
            let s = b"unknown\0";
            for (n, b) in s.iter().enumerate() {
                *flagstr.offset(n as isize) = *b as c_char;
            }
        }

        flagstr
    }
}

/// Raven `G_TestLine`.
///
/// Source: `oracle/oracle/codemp/game/ai_wpnav.c:212-222`
pub fn G_TestLine(
    ctx: GameContext<'_>,start: vec3_t, end: vec3_t, color: c_int, time: c_int) {
    let ev_testline = mp_bg::public::entity_event::entity_event_t::EV_TESTLINE as c_int;
    // `SVF_BROADCAST` (svflags #define) is not yet ported anywhere in the
    // crate graph; defined locally, verbatim.
    // Source: `oracle/oracle/codemp/game/g_public.h:20`
    const SVF_BROADCAST: c_int = 0x00000020;

    unsafe {
        let te = G_TempEntity(ctx, start, ev_testline);
        (*te).s.origin = start;
        (*te).s.origin2 = end;
        (*te).s.time2 = time;
        (*te).s.weapon = color;
        (*te).r.svFlags |= SVF_BROADCAST;
    }
}

